using static Revathryn.Contracts.Consts;

namespace Revathryn.Engine
{
    /// <summary>Hardcoded catalog of built-in review definitions.</summary>
    internal static class DefaultReviewTypes
    {
        /// <summary>All built-in review definitions.</summary>
        public static IReadOnlyList<ReviewTypeDefinition> All { get; } = Build();

        private static IReadOnlyList<ReviewTypeDefinition> Build()
        {
#pragma warning disable CC0009
            return
            [
                new("correctness", "Correctness", "Evaluates whether the code behaves as intended under all expected conditions.\r\nChecks for logical flaws, incorrect assumptions, edge‑case failures, off‑by‑one errors, misuse of APIs, race conditions, and mismatches between implementation and specification.\r\nAlso examines data flow, state transitions, and whether invariants are preserved", 1, FileTypeCSharp),
                new("security", "Security", "Assesses how the code handles untrusted input, sensitive data, and external interfaces.\r\nChecks for injection risks, unsafe deserialization, insecure defaults, missing validation, improper authentication/authorization, weak cryptography usage, and exposure of internal details.\r\nAlso reviews error messages for information leakage and verifies adherence to secure coding practices.", 1, FileTypeCSharp),
                new("error-handling", "Error handling", "Evaluates robustness under failure conditions.\r\nChecks whether exceptions are correctly caught or propagated, resources are reliably cleaned up, and failure modes are predictable and safe.\r\nReviews retry logic, fallback behaviour, logging quality, and whether the code avoids swallowing errors or masking root causes.", 1, FileTypeCSharp),
                new("performance", "Performance", "Analyzes algorithmic efficiency, memory usage, and I/O patterns.\r\nChecks for unnecessary allocations, excessive copying, blocking operations, inefficient loops, redundant work, and misuse of data structures.\r\nAlso considers scalability, concurrency behaviour, and whether performance trade‑offs are appropriate for the context.", 1, FileTypeCSharp),
                new("maintainability", "Maintainability", "Evaluates readability, structure, and long‑term sustainability of the code.\r\nChecks naming clarity, modularity, separation of concerns, duplication, dead code, comment quality, and adherence to architectural conventions.\r\nAlso reviews testability, cohesion, coupling, and whether future changes can be made safely and predictably.", 1, FileTypeCSharp),
                new("api-interface-design", "API & Interface Design", "Evaluates how public‑facing functions, classes, and modules are structured.\r\nChecks clarity of contracts, consistency of naming, parameter ergonomics, stability of interfaces, and whether abstractions leak internal details.\r\nAlso reviews whether the API is intuitive, predictable, and easy to use correctly.", 1, FileTypeCSharp),
                new("concurrency-parallelism", "Concurrency & Parallelism", "Assesses correctness and safety in multi‑threaded or asynchronous code.\r\nChecks for race conditions, deadlocks, improper locking, shared‑state hazards, starvation, and misuse of async primitives.\r\nAlso evaluates scheduling assumptions, atomicity, and whether concurrency improves or harms performance.", 1, FileTypeCSharp),
                new("resource-management", "Resource Management", "Evaluates how the code acquires, uses, and releases finite resources.\r\nChecks for leaks, premature disposal, unbounded growth, file handle misuse, connection pooling issues, and correct lifetime management.\r\nAlso reviews cleanup guarantees under both normal and exceptional control flow.", 1, FileTypeCSharp),
                new("data-validation-input-sanity", "Data Validation & Input Sanity", "Assesses how the code validates, normalizes, and constrains incoming data.\r\nChecks for missing validation, overly permissive parsing, incorrect assumptions about shape or type, and unsafe transformations.\r\nAlso evaluates whether validation is centralized, consistent, and aligned with domain rules.", 1, FileTypeCSharp),
                new("testing-quality", "Testing Quality", "Evaluates the presence, structure, and effectiveness of tests related to the code.\r\nChecks coverage of critical paths, clarity of test intent, isolation, determinism, fixture quality, and whether tests meaningfully assert behaviour rather than implementation details.\r\nAlso reviews whether edge cases and failure modes are exercised.", 1, FileTypeCSharp),
                new("documentation-comments", "Documentation & Comments", "Assesses clarity and usefulness of inline comments, docstrings, and external documentation.\r\nChecks whether comments explain why rather than what, whether documentation matches behaviour, and whether complex logic is adequately described.\r\nAlso evaluates readability of examples and correctness of usage notes.", 1, FileTypeCSharp),
                new("architecture-design-quality", "Architecture & Design Quality", "Evaluates how the code fits into the broader system architecture.\r\nChecks adherence to design principles (SOLID, layering, separation of concerns), modularity, dependency direction, and whether the implementation aligns with architectural intent.\r\nAlso reviews whether the design scales with future requirements.", 1, FileTypeCSharp),
                new("configuration-environment-handling", "Configuration & Environment Handling", "Assesses how the code interacts with configuration, environment variables, and external systems.\r\nChecks for hard‑coded values, unsafe defaults, missing validation, improper fallback behaviour, and environment‑specific assumptions.\r\nAlso evaluates whether configuration is centralized, documented, and override‑friendly.", 1, FileTypeCSharp),
                new("logging-observability", "Logging & Observability", "Evaluates how the code emits logs, metrics, and traces.\r\nChecks for missing critical logs, overly verbose logging, sensitive data exposure, inconsistent log levels, and lack of correlation identifiers.\r\nAlso reviews whether emitted signals support debugging, monitoring, and incident response.", 1, FileTypeCSharp),
                new("dependency-package-hygiene", "Dependency & Package Hygiene", "Assesses how external libraries and internal modules are used.\r\nChecks for unnecessary dependencies, outdated versions, unsafe transitive imports, circular references, and tight coupling.\r\nAlso evaluates whether dependency boundaries are clean and intentional.", 1, FileTypeCSharp),
                new("ux-developer-experience", "UX / Developer Experience", "Evaluates how the code affects the experience of its users—developers or end‑users.\r\nChecks clarity of error messages, helpfulness of prompts, consistency of behaviour, and whether the tool is intuitive and forgiving.\r\nAlso reviews whether defaults are sensible and workflows are smooth.", 1, FileTypeCSharp),
                new("memory-safety", "Memory Safety", "Evaluates native memory handling for buffer overflows, out‑of‑bounds access, use‑after‑free, double‑free, null or dangling pointer dereferences, integer overflow in size calculations, and failure to validate allocation results.\r\nChecks ownership of every pointer and buffer, ensuring every allocation is freed exactly once and every read/write stays within the object lifetime.", 1, CEpExtensions),
                new("undefined-behaviour", "Undefined Behaviour", "Assesses native code for operations that violate the C/C++ language rules.\r\nChecks signed integer overflow, shift by invalid amounts, aliasing violations, unsequenced modification, invalid casts, misaligned access, and reliance on unspecified evaluation order.\r\nAlso verifies that reliance on implementation‑defined or unspecified behaviour is deliberate and documented.", 1, CEpExtensions),
                new("object-lifetime-raii", "Object Lifetime & RAII", "Evaluates construction, destruction, and resource ownership in C++ types.\r\nChecks constructor/destructor correctness, copy and move semantics, the rule of zero/three/five, member initialization order, and whether resources are acquired in constructors and released in destructors.\r\nAlso reviews exception safety of constructors and whether raw owning pointers should be smart pointers or containers.", 1, CEpExtensions),
                new("concurrency-synchronization", "Concurrency & Synchronization", "Assesses correctness and safety of threaded native code.\r\nChecks data races, missing or overly broad locking, lock ordering and deadlock potential, atomicity of shared state, memory ordering, and safe publication of shared objects.\r\nAlso reviews use of atomics, condition variables, and whether thread‑safety guarantees are documented.", 1, CEpExtensions),
                new("const-correctness", "Const‑Correctness", "Evaluates how consistently const qualifiers express and enforce immutability.\r\nChecks whether functions that do not modify state are marked const, whether parameters that are not mutated are passed by const reference or value, and whether mutable state is scoped correctly.\r\nAlso reviews const_cast usage and whether const overloads behave consistently.", 1, CEpExtensions),
                new("value-vs-reference-semantics", "Value vs Reference Semantics", "Assesses whether types are passed and returned with appropriate semantics.\r\nChecks pass‑by‑value versus const reference versus pointer choices, ownership transfer versus borrowing, and whether classes define value or reference semantics consistently.\r\nAlso reviews whether small types are copied cheaply and large types are moved or referenced.", 1, CEpExtensions),
                new("error-handling-c-cpp", "Error Handling (C/C++ specific)", "Evaluates how native code detects, reports, and recovers from failures.\r\nChecks return‑code and errno handling, error propagation through call stacks, exception safety guarantees, and whether failures leave resources and invariants intact.\r\nAlso reviews whether error paths are tested and whether failure modes are distinguishable.", 1, CEpExtensions),
                new("header-hygiene", "Header Hygiene", "Evaluates header structure, self‑containment, and include discipline.\r\nChecks for missing or redundant includes, include guards or pragma once, forward declarations versus full definitions, and minimal header dependencies.\r\nAlso reviews whether headers expose implementation details, pollute global scope, or cause excessive compilation coupling.", 1, CEpExtensions),
                new("safety-wrappers-modern-cpp", "Safety Wrappers & Modern C++ Usage", "Assesses use of modern C++ facilities that reduce risk.\r\nChecks adoption of smart pointers, containers, RAII wrappers, span and string_view, type‑safe alternatives to C APIs, and constexpr where appropriate.\r\nAlso reviews unsafe legacy idioms such as raw new/delete, C‑style casts, and manual resource management.", 1, CEpExtensions),
                new("performance-native", "Performance (Native‑specific)", "Analyzes native performance characteristics.\r\nChecks allocation frequency, cache locality, object layout and padding, move versus copy, virtual dispatch overhead, and algorithmic efficiency of hot paths.\r\nAlso reviews whether optimizations are justified, measurable, and do not compromise safety or clarity.", 1, CEpExtensions),
                new("abi-interface-stability", "ABI & Interface Stability", "Evaluates binary compatibility and public interface stability.\r\nChecks layout changes to exported types, virtual table stability, symbol visibility, calling conventions, and breaking changes to shared library interfaces.\r\nAlso reviews versioning, export macros, and whether consumers are protected from internal representation changes.", 1, CEpExtensions),
                new("translations", "Translated Strings", "Identify hardcoded strings intended for display to end users that are not stored in the application's existing localisation/resource infrastructure. Exclude technical, internal, logging and diagnostic strings, and report each finding with its location, explaining why it should be moved into a resource file to support translation. Any findings should be marked Critical", 50, ".cs")
            ];
#pragma warning restore CC0009
        }
    }
}
